436	function readWorkerProposalInvocationPrivateKey(
437	  env: NodeJS.ProcessEnv,
438	): string | undefined {
439	  const rawFd = env.LATTICE_MANAGED_HOST_WORKER_CAPABILITY_FD?.trim();
440	  if (!rawFd) return undefined;
441	  const fd = Number(rawFd);
442	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
443	    throw new Error('managed host run worker: proposal capability fd must be between 3 and 255');
444	  }
445	  const stat = fstatSync(fd);
446	  if (stat.isFile()) {
447	    throw new Error('managed host run worker: proposal capability must arrive over a non-file descriptor');
448	  }
449	  const key = readFileSync(fd, 'utf8').trim();
450	  if (!/^[A-Za-z0-9+/]{43}=$/.test(key)) {
451	    throw new Error('managed host run worker: proposal capability descriptor is malformed');
452	  }
453	  return key;
454	}
