534	  const parent = dirname(worktree);
535	  if (basename(worktree) !== 'worktree'
536	    || !basename(parent).startsWith('lattice-xhr-review-')
537	    || dirname(parent) !== tmpdir()) {
538	    throw new Error(`managed host run: cross-host review snapshot is outside the canonical temporary boundary: ${worktree}`);
539	  }
540	  if (!existsSync(worktree)) {
541	    const registeredWorktrees = execFileSync('git', ['worktree', 'list', '--porcelain'], {
542	      cwd: gitCwd,
543	      encoding: 'utf8',
544	      stdio: ['ignore', 'pipe', 'pipe'],
545	      maxBuffer: 8 * 1024 * 1024,
546	    });
547	    const registered = registeredWorktrees
548	      .split('\n')
549	      .some(line => line === `worktree ${resolve(worktree)}`);
550	    if (!registered) {
551	      rmSync(parent, { recursive: true, force: true });
552	      return;
553	    }
